VAL = {'baseline': (12, 10, 18, 110), 'logistic': (21, 12, 9, 108), 'tree': (24, 17, 6, 103)}   # (TP, FP, FN, TN) on 150 validation customers
def metrics(tp, fp, fn, tn):
    p = tp / (tp + fp)
    r = tp / (tp + fn)
    return {'accuracy': (tp + tn) / (tp + fp + fn + tn), 'precision': p, 'recall': r, 'f1': 2 * p * r / (p + r)}
def meets_goal(m):
    return m['recall'] >= 0.75 and m['precision'] >= 0.5
m = metrics(*VAL['logistic'])
print('F1', round(m['f1'], 2), 'recall', round(m['recall'], 2), 'meets goal:', meets_goal(m))
# prints: F1 0.67 recall 0.7 meets goal: False

RESULTS = [(1, 0.48, 0.46), (2, 0.62, 0.58), (4, 0.76, 0.676), (8, 0.97, 0.59)]   # (max_depth, train F1, validation F1)
def diagnose(train, valid):
    gap = train - valid
    if train < 0.65 and valid < 0.65 and gap < 0.10:
        return 'underfitting'
    if gap > 0.20:
        return 'overfitting'
    return 'no clear fit problem'
for d, tr, va in (RESULTS[0], RESULTS[3]):
    print('depth', d, '->', diagnose(tr, va))
# prints: depth 1 -> underfitting
# prints: depth 8 -> overfitting

